function EXACT-OPTIMUM(N, m):
    require m >= 1
    q <- floor(N / m)          # balanced bucket size
    r <- N mod m               # number of overloaded buckets
    T(k) := k*(k+1)/2          # cost of scanning a bucket of size k
    return r * T(q+1) + (m - r) * T(q)

function OPTIMUM-AND-PROFILE(N, m):
    q, r <- floor(N/m), N mod m
    profile <- [q+1 repeated r times] ++ [q repeated (m-r) times]
    return (EXACT-OPTIMUM(N, m), profile)   # profile sums to N and attains the optimum

function RESIDUE-SCHEME(N, m):
    return [ x mod m  for x = 0 .. N-1 ]

function SCAN-LISTS(bucket_map, m):
    lists <- array of m empty lists
    for x = 0 .. N-1 in increasing key order:
        append x to lists[bucket_map[x]]     # keys enter in scan order
    return lists

function BUILD-INDEX(bucket_map, m):
    code <- empty map
    for b = 0 .. m-1:
        for (i, x) in enumerate(SCAN-LISTS(bucket_map, m)[b]):
            code[x] <- (b, i)                # scan code of x
    return code                              # injective; decode(b,i) = lists[b][i]

function TOTAL-COST(bucket_map, m):
    return sum over buckets b of T(|lists[b]|)   # exact cost accounting

