from typing import Dict, List


def residue_scheme(n: int, m: int) -> List[int]:
    """The bucket map x -> x mod m on keys 0..n-1: a provably cost-optimal scheme."""
    if m <= 0:
        raise ValueError("the number of buckets must be positive")
    return [x % m for x in range(n)]


def scan_lists(bucket_map: List[int], m: int) -> List[List[int]]:
    """The ordered contents of each bucket (keys in increasing order)."""
    lists: List[List[int]] = [[] for _ in range(m)]
    for x, b in enumerate(bucket_map):
        lists[b].append(x)
    return lists


def build_index(bucket_map: List[int], m: int) -> Dict[int, tuple[int, int]]:
    """Assign every key its scan code (bucket label, intra-bucket index).

    The resulting map is injective and its inverse is read off by indexing the
    bucket's scan list, so the code is uniquely decodable. O(n + m) time.
    """
    code: Dict[int, tuple[int, int]] = {}
    for b, lst in enumerate(scan_lists(bucket_map, m)):
        for i, x in enumerate(lst):
            code[x] = (b, i)
    return code


def total_cost(bucket_map: List[int], m: int) -> int:
    """Total decoding cost, computed by the exact accounting identity."""
    return sum(triangle(len(lst)) for lst in scan_lists(bucket_map, m))

