function OPTIMALITY-CERTIFICATE(bucket_map, m):
    N <- length(bucket_map);  require m >= 1
    sizes <- array of m zeros
    for b in bucket_map: sizes[b] <- sizes[b] + 1
    q <- floor(N / m)
    for b = 0 .. m-1:
        if not (q <= sizes[b] <= q + 1):
            return (FALSE, b)        # witness: this bucket breaks optimality
    return (TRUE, none)              # every bucket balanced  <=>  cost = Opt(N,m)

function EXCESS-COST(bucket_map, m):
    compute sizes and q as above
    return sum over b of (sizes[b]-q)*(sizes[b]-q-1)/2    # = total cost - Opt(N,m)

