from typing import List, Optional, Tuple


def optimality_certificate(bucket_map: List[int], m: int) -> Tuple[bool, Optional[int]]:
    """Decide cost-optimality of a scheme in O(n + m), by the rigidity theorem.

    Returns (True, None) if every bucket holds floor(n/m) or ceil(n/m) keys --
    which is equivalent to the scheme attaining the exact optimum -- and
    (False, b) naming an offending bucket b otherwise.
    """
    n = len(bucket_map)
    if m <= 0:
        raise ValueError("the number of buckets must be positive")
    sizes = [0] * m
    for b in bucket_map:
        sizes[b] += 1
    q = n // m
    for b, k in enumerate(sizes):
        if not (q <= k <= q + 1):
            return False, b
    return True, None


def excess_cost(bucket_map: List[int], m: int) -> int:
    """How far above the optimum a scheme is: the sum of the per-bucket slacks."""
    n = len(bucket_map)
    q = n // m
    sizes = [0] * m
    for b in bucket_map:
        sizes[b] += 1
    return sum((k - q) * (k - q - 1) // 2 for k in sizes)

