function PARTITIONS-AT-MOST(n, parts, cap):
    if n = 0: yield []  and return
    if parts = 0: return
    for p = min(n, cap) down to 1:
        for rest in PARTITIONS-AT-MOST(n - p, parts - 1, p):
            yield [p] ++ rest        # weakly decreasing, so each multiset once

function ACHIEVABLE-COST-SET(N, m):
    S <- empty set
    for P in PARTITIONS-AT-MOST(N, m, N):
        S <- S union { sum of T(k) for k in P }
    return sorted(S)

function SPECTRUM-GAPS(N, m):
    hits <- ACHIEVABLE-COST-SET(N, m)
    return [ c in Opt(N,m) .. T(N) : c not in hits ]

