from typing import Iterator, List


def partitions_at_most(n: int, parts: int, cap: int) -> Iterator[List[int]]:
    """Weakly decreasing partitions of n into at most `parts` parts, each <= cap."""
    if n == 0:
        yield []
        return
    if parts == 0:
        return
    for p in range(min(n, cap), 0, -1):
        for rest in partitions_at_most(n - p, parts - 1, p):
            yield [p] + rest


def achievable_cost_set(n: int, m: int) -> List[int]:
    """Every total decoding cost realisable by some scheme on n keys, m buckets.

    By exact cost accounting the total depends only on the multiset of bucket
    sizes, so the achievable set is exactly the set of sums of triangular numbers
    over partitions of n into at most m parts. This costs O(p(n, m)) work rather
    than the O(m^n) of naive enumeration over bucket maps.
    """
    return sorted({sum(triangle(k) for k in p) for p in partitions_at_most(n, m, n)})


def spectrum_gaps(n: int, m: int) -> List[int]:
    """The integers inside the cost window that no scheme can realise."""
    hits = set(achievable_cost_set(n, m))
    return [c for c in range(exact_optimum(n, m), triangle(n) + 1) if c not in hits]
